import{_ as t,o as r,c as a,ae as o}from"./chunks/framework.BX6FPmO9.js";const m=JSON.parse('{"title":"Spec Review 規範（開發前）","description":"","frontmatter":{},"headers":[],"relativePath":"spec-review.md","filePath":"spec-review.md"}'),s={name:"spec-review.md"};function d(i,e,c,l,p,n){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="spec-review-規範-開發前" tabindex="-1">Spec Review 規範（開發前） <a class="header-anchor" href="#spec-review-規範-開發前" aria-label="Permalink to &quot;Spec Review 規範（開發前）&quot;">​</a></h1><p><strong>類型</strong>：spec | <strong>權重</strong>：1</p><p>本文件為 <strong>feature / ticket 開工前</strong>的規格審查標準，與 <a href="./code-review-spec.html">code-review-spec.md</a>（<strong>階段後</strong>規格對齊）互補、不重複。目的：先確認 spec 完整、無 drift、影響面清楚，再動程式碼。適用對象：<strong>開發者</strong>與 <strong>AI（Coding / Review Agent）</strong>。</p><p>Canonical workflow（工具無關、跨 repo）：<a href="https://github.com/tessOu56/develop-md/blob/main/ai-skills/spec-review/SKILL.md" target="_blank" rel="noreferrer">develop-md/ai-skills/spec-review/SKILL.md</a>。本文件只定義 portal 內的落地細節。</p><hr><h2 id="_1-使用時機" tabindex="-1">1. 使用時機 <a class="header-anchor" href="#_1-使用時機" aria-label="Permalink to &quot;1. 使用時機&quot;">​</a></h2><ul><li>接到 platform-inbox ticket 或自發 feature，<strong>寫第一行程式碼之前</strong>。</li><li>變更涉及對外 HTTP 形狀、domain 狀態機、datacontract、policy 時<strong>必做</strong>；純文件或不動契約的小修可略過，但 PR 仍須填 spec impact。</li></ul><h2 id="_2-審查步驟-portal-版" tabindex="-1">2. 審查步驟（portal 版） <a class="header-anchor" href="#_2-審查步驟-portal-版" aria-label="Permalink to &quot;2. 審查步驟（portal 版）&quot;">​</a></h2><ol><li><strong>讀上游</strong>：<a href="./../AGENTS.html">AGENTS.md</a> → <a href="./../specs/README.html">specs/README.md</a> → 相關 <a href="./adr/">docs/adr/</a>、<a href="./../specs/domain/">specs/domain/</a>、<a href="./../specs/datacontracts/">specs/datacontracts/</a>。</li><li><strong>Drift 檢查</strong>： <ul><li>Zod（<code>packages/shared-contracts</code>）↔ <code>specs/openapi/openapi.yaml</code> 是否對齊（過渡期規則：先 Zod、再 OpenAPI）</li><li><code>pnpm run verify:openapi-codegen</code>（generated 是否 stale）</li><li><a href="./../specs/api/handler-mapping.html">specs/api/handler-mapping.md</a> ↔ <code>app/test/handlers.ts</code> 是否涵蓋</li></ul></li><li><strong>缺漏檢查</strong>：feature 需要但 spec 未定義的 domain rule、錯誤碼（<code>errorResponseSchema</code>）、權限規則（<code>specs/policies/</code>）。</li><li><strong>影響面與計畫</strong>：impacted spec files、契約是否 breaking、implementation plan（spec → 契約 → codegen → 實作 → test）。</li><li><strong>裁決</strong>：<code>ready</code> / <code>ready-with-notes</code> / <code>blocked</code>。<strong>blocked＝先補 spec，不先寫碼。</strong></li></ol><h2 id="_3-產出與存放" tabindex="-1">3. 產出與存放 <a class="header-anchor" href="#_3-產出與存放" aria-label="Permalink to &quot;3. 產出與存放&quot;">​</a></h2><ul><li>報告依 <a href="https://github.com/tessOu56/develop-md/blob/main/ai-skills/spec-review/templates/spec-review-report.md" target="_blank" rel="noreferrer">develop-md 模板</a> 填寫，存 <a href="./../code-review/spec-reviews/">code-review/spec-reviews/</a>，檔名 <code>YYYY-MM-DD-&lt;slug&gt;.md</code>。</li><li>報告 §8（spec impact 摘要）於 PR 時貼入 PR template 對應欄位。</li><li>審查發現的既存問題若不在本 feature 範圍：登錄 <code>code-review/issues.md</code>（CR-xxx），不順手改。</li></ul><h2 id="_4-與其他制度的關係" tabindex="-1">4. 與其他制度的關係 <a class="header-anchor" href="#_4-與其他制度的關係" aria-label="Permalink to &quot;4. 與其他制度的關係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>制度</th><th>時機</th><th>入口</th></tr></thead><tbody><tr><td><strong>Spec review（本文件）</strong></td><td>開工前</td><td>code-review/spec-reviews/</td></tr><tr><td>Code review</td><td>階段後 / PR 前</td><td><a href="./code-review-spec.html">code-review-spec.md</a> ＋ CR-xxx</td></tr><tr><td>Architecture review</td><td>季度 / wave 收尾</td><td>develop-md <code>reports/architecture-reviews/</code></td></tr><tr><td>PR 守門</td><td>每個 PR</td><td><code>.github/pull_request_template.md</code> spec impact 欄</td></tr></tbody></table>',13)])])}const g=t(s,[["render",d]]);export{m as __pageData,g as default};
